// Generates src/data/mock/{league}.ts files from standings-snapshot.json.
// Real team names, crests, points, played, W/D/L, GF/GA come from football-data.org.
// Synthetic squads/scorers/assists/matches are still generated by createMockLeague
// (because squad data requires per-team API calls that exceed the free tier rate limit).
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, resolve } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const snapshot = JSON.parse(readFileSync(resolve(root, 'standings-snapshot.json'), 'utf8'))

const codeToLeague = {
  PL: { id: 'premier-league', seed: 7 },
  BL1: { id: 'bundesliga', seed: 11 },
  PD: { id: 'la-liga', seed: 17 },
  SA: { id: 'serie-a', seed: 23 },
  FL1: { id: 'ligue-1', seed: 29 },
}

