function pickColor(name) {
  return colors[name] ?? '#475569'
}

// Form letters per team derived deterministically from W/D/L ratios.
function generateForm(t, position) {
  const total = Math.max(1, t.won + t.drawn + t.lost)
  const wRatio = t.won / total
  const dRatio = t.drawn / total
  const seq = []
  // Seeded pseudo-random so the form is stable across reloads.
  let s = (t.position * 9301 + 49297) % 233280
  for (let i = 0; i < 5; i += 1) {
    s = (s * 9301 + 49297) % 233280
    const r = s / 233280
    if (r < wRatio) seq.push('W')
    else if (r < wRatio + dRatio) seq.push('D')
    else seq.push('L')
  }
  void position
  return seq
}

function tsString(s) {
  // Escape backslashes and single quotes, keep unicode intact.
  return "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'"
}

function emit(code) {
  const { id, seed } = codeToLeague[code]
  const block = snapshot[code]
  const teams = block.table.map((t) => ({
    name: t.name,
    shortName: t.shortName || t.tla,
    tla: (t.tla || t.shortName || t.name).trim().toUpperCase().slice(0, 3),
    crest: t.crest,
    color: pickColor(t.name),
    points: t.points,
    played: t.played,
    won: t.won,
    drawn: t.drawn,
    lost: t.lost,
    goalsFor: t.gf,
    goalsAgainst: t.ga,
    form: generateForm(t, t.position),
  }))

  const lines = [
    "import { createMockLeague } from './createMockLeague'",
    '',
    '// Auto-generated from standings-snapshot.json (real 2025-26 data via football-data.org).',
    '// Run `node scripts/build-mock-data.mjs` to regenerate after refreshing the snapshot.',
    `const realTeams = [`,
    ...teams.map(
      (t) =>
        `  { name: ${tsString(t.name)}, shortName: ${tsString(t.shortName)}, tla: ${tsString(
          t.tla,
        )}, crest: ${tsString(t.crest)}, color: ${tsString(t.color)}, points: ${t.points}, played: ${
          t.played
        }, won: ${t.won}, drawn: ${t.drawn}, lost: ${t.lost}, goalsFor: ${t.goalsFor}, goalsAgainst: ${
          t.goalsAgainst
        }, form: [${t.form.map((f) => `'${f}'`).join(', ')}] as const },`,
    ),
    `] as const`,
    '',
    `export const { standings, topScorers, topAssists, recentMatches, teams } = createMockLeague({`,
    `  leagueId: '${id}',`,
    `  seed: ${seed},`,
    `  realTeams: realTeams.map((t) => ({ ...t, form: [...t.form] })),`,
    `})`,
    '',
  ].join('\n')

  const filename = id + '.ts'
  writeFileSync(resolve(root, 'src/data/mock', filename), lines, 'utf8')
  console.log(`wrote src/data/mock/${filename} (${teams.length} teams)`)
}

for (const code of Object.keys(codeToLeague)) emit(code)
